define("mod_seledascorm/learner_layout",[],function(){
// GPL-3.0-or-later. Keep Moodle's tree and sequencing; enhance its presentation.
const init = (labels = {}) => {
    const page = document.getElementById('seledascormpage');
    const toc = document.getElementById('seledascorm_toc');
    const toggle = document.getElementById('seledascorm_toc_toggle_btn');
    const content = document.getElementById('seledascorm_content');
    if (!page || !toc || !toggle || !content || page.dataset.seledaLayout) return;
    page.dataset.seledaLayout = '1';
    const media = matchMedia('(max-width:768px)');
    const originalRole = toc.getAttribute('role') || 'navigation';
    const originalInert = content.inert;
    const heading = document.createElement('div');
    heading.className = 'seleda-toc-heading';
    const title = document.createElement('span');
    title.textContent = labels.contents || 'Course contents';
    const close = document.createElement('button');
    close.type = 'button'; close.className = 'seleda-toc-close';
    close.setAttribute('aria-label', labels.close || 'Close course contents');
    close.textContent = '×';
    heading.append(title, close); toc.prepend(heading);
    const shade = document.createElement('button');
    shade.type = 'button'; shade.className = 'seleda-toc-backdrop';
    shade.setAttribute('aria-label', labels.close || 'Close course contents');
    shade.tabIndex = -1; shade.hidden = true; page.append(shade);
    let wasOpen = false, scheduled = false, returnFocus = true;
    const isOpen = () => media.matches && !toc.classList.contains('disabled');
    const hide = () => { if (!toc.classList.contains('disabled')) toggle.click(); };
    close.addEventListener('click', hide); shade.addEventListener('click', hide);
    function sync() {
        const open = isOpen();
        page.classList.toggle('seleda-drawer-open', open);
        toc.inert = media.matches && !open;
        content.inert = open || originalInert;
        shade.hidden = !open;
        toc.setAttribute('role', media.matches ? 'dialog' : originalRole);
        if (media.matches) toc.setAttribute('aria-modal', 'true'); else toc.removeAttribute('aria-modal');
        toggle.setAttribute('aria-expanded', String(!toc.classList.contains('disabled')));
        const label = toc.classList.contains('disabled') ? labels.open || 'Open course contents' : labels.close || 'Close course contents';
        toggle.setAttribute('aria-label', label);
        if (open && !wasOpen) close.focus({preventScroll:true});
        if (!open && wasOpen) {
            if (returnFocus) toggle.focus({preventScroll:true});
            else content.querySelector('iframe')?.focus({preventScroll:true});
            returnFocus = true;
        }
        wasOpen = open;
    }
    // Keep a newly opened narrow player closed until the learner asks for the tree.
    if (media.matches && !toc.classList.contains('disabled')) {
        toc.classList.add('disabled'); toc.setAttribute('disabled-by','screen-size');
    }
    toc.addEventListener('click', event => {
        if (media.matches && event.target.closest('a')) { returnFocus = false; setTimeout(hide, 0); }
    });
    document.addEventListener('keydown', event => {
        if (!isOpen()) return;
        if (event.key === 'Escape') { event.preventDefault(); hide(); return; }
        if (event.key !== 'Tab') return;
        const controls = [...toc.querySelectorAll('a[href],button,[tabindex]:not([tabindex="-1"])')]
            .filter(node => !node.disabled && node.getClientRects().length);
        controls.push(toggle);
        const index = controls.indexOf(document.activeElement);
        if (event.shiftKey && index <= 0) { event.preventDefault(); controls.at(-1).focus(); }
        else if (!event.shiftKey && (index === controls.length - 1 || index < 0)) { event.preventDefault(); controls[0].focus(); }
    });
    // Native YUI code owns open/closed state, including user choices and resize.
    new MutationObserver(() => {
        if (scheduled) return;
        scheduled = true; queueMicrotask(() => { scheduled = false; sync(); });
    }).observe(toc,{attributes:true,attributeFilter:['class']});
    media.addEventListener('change', sync);
    sync();
};

return {init};
});
